/**
 * The shapes the API returns, taken from the server's OpenAPI document
 * (`./openapi.d.ts`, regenerated by `just api-types`) so they cannot drift from
 * what the server sends. The nested routes take `research_group` from the
 * path, so it is not a field.
 */

import type { components } from "./openapi";

type Schemas = components["schemas"];

export type Group = Schemas["ResearchGroupRead"];

export type Member = Schemas["MemberOut"];

export type ResearchGroupRole = Schemas["ResearchGroupRoleEnum"];

export type FishTankEntry = Schemas["TankEntryOut"];

export type CabinetEntry = Schemas["CabinetEntryOut"];

/** A study with everything beneath it, as `GET /api/studies/{id}` returns it. */
export type Study = Schemas["StudyRead"];

/** What `POST` and `PUT` accept for a study: its own fields, no experiments. */
export type StudyBody = Schemas["StudyInput"];
